"""A pickled constant in two graphs is the same constant when its VALUES are, whatever bytes
each torch wrote.

TinyLlama re-traced on the engine environment (torch 2.14) against its July container (torch
2.5): every rotary table's `constant_data` differed as bytes and matched as values, and the
gate counted each as a difference beyond the annotation. The two fixtures below are that very
tensor — `block.9.attn.rotary_embed.inv_freq`, 32 bfloat16 values — as torch 2.5.1 (ml/venv)
and torch 2.14.0 (nbx_t214) pickled it from the SAME Forge on 2026-09-26 04:26 UTC. Seen RED on
retrace-2026-09-26 a7d62766 (bytes compared).
Run: python -m pytest tests/unit/tools/test_retrace_gate_compares_a_constant_by_value.py
"""
from __future__ import annotations

import base64
import io
import sys
from pathlib import Path

import torch

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "tools"))
import retrace_zoo as R  # noqa: E402

INV_FREQ_TORCH_2_5 = ""
INV_FREQ_TORCH_2_14 = ""


def _pickled(t):
    buf = io.BytesIO()
    torch.save(t, buf)
    return base64.b64encode(buf.getvalue()).decode()


def test_the_same_tensor_pickled_by_two_torches_is_equal():
    assert INV_FREQ_TORCH_2_5 != INV_FREQ_TORCH_2_14
    assert R.constants_equal(INV_FREQ_TORCH_2_5, INV_FREQ_TORCH_2_14)


def test_different_values_or_dtypes_or_shapes_differ():
    t = torch.load(io.BytesIO(base64.b64decode(INV_FREQ_TORCH_2_14)), weights_only=True)
    assert not R.constants_equal(_pickled(t), _pickled(t + 1))
    assert not R.constants_equal(_pickled(t), _pickled(t.float()))
    assert not R.constants_equal(_pickled(t), _pickled(t[:16]))
    assert not R.constants_equal(_pickled(t), None) and not R.constants_equal("not base64!", _pickled(t))
